"""Contextual editing regression checks against the real running Vue demo."""
import json,os
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
OUT=Path(__file__).resolve().parents[1]/'artifacts';checks=[]
with sync_playwright() as p:
 b=p.chromium.launch();page=b.new_page(viewport={'width':1440,'height':1100});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(os.environ.get('INKWELL_URL','http://127.0.0.1:8844'),wait_until='networkidle');editor=page.get_by_role('textbox',name='Draft document',exact=True);page.get_by_text('Test an external content update',exact=True).click()
 def replace(text):page.get_by_label('HTML source',exact=True).fill(text);page.get_by_role('button',name='Replace document',exact=True).click()
 def select():
  editor.locator('p').first.click();mac=page.evaluate("navigator.platform.includes('Mac')");editor.press('Meta+ArrowUp' if mac else 'Control+Home');editor.press('Meta+Shift+ArrowDown' if mac else 'Control+Shift+End');page.evaluate('() => new Promise(requestAnimationFrame)')
 def floating():return page.get_by_role('toolbar',name='Selection formatting',exact=True)
 def context():return page.get_by_role('menu',name='Text editing',exact=True)
 replace('<p>Useful selected words</p>');select();expect(floating()).to_be_visible();expect(floating()).to_contain_text('3 words');page.get_by_role('button',name='Selection bold',exact=True).click();expect(editor.locator('strong')).to_have_text('Useful selected words');checks.append('Selection toolbar exposes selected word count and applies bold to retained range.')
 select();page.get_by_role('button',name='Selection link',exact=True).click();expect(page.get_by_label('Link address',exact=True)).to_be_focused();page.get_by_label('Link address',exact=True).fill('https://example.com/selected');page.get_by_role('button',name='Apply link',exact=True).click();expect(editor.locator('a')).to_have_text('Useful selected words');expect(editor.locator('a')).to_have_attribute('href','https://example.com/selected');checks.append('Floating link popover retains the selected text while entering a URL.')
 select();editor.press('Shift+F10');expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();expect(context()).to_be_visible();expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();page.keyboard.press('ArrowDown');expect(context().get_by_role('menuitemcheckbox',name='Italic',exact=True)).to_be_focused();page.keyboard.press('Enter');expect(editor.locator('em')).to_have_text('Useful selected words');expect(context()).to_have_count(0);checks.append('Shift+F10 opens menu; arrow navigation and Enter apply formatting.')
 select();editor.press('Shift+F10');expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();page.keyboard.press('End');expect(context().get_by_role('menuitem',name='Clear formatting')).to_be_focused();page.keyboard.press('Enter');expect(editor.locator('strong,em,a')).to_have_count(0);checks.append('Keyboard context clear formatting removes marks without replacing text.')
 select();editor.press('Shift+F10');expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();page.keyboard.press('Escape');expect(context()).to_have_count(0);expect(editor).to_be_focused();editor.press('ArrowRight');page.keyboard.type('!');expect(editor).to_have_text('Useful selected words!');checks.append('Escape closes menu and returns focus to unchanged document range.')
 editor.click(button='right');expect(context()).to_be_visible();page.get_by_role('heading',name='A blank page. Every possibility.').click();expect(context()).to_have_count(0);checks.append('Pointer right-click opens context menu; outside click dismisses.')
 select();editor.press('Shift+F10');expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();page.get_by_label('Read only',exact=True).check();expect(context()).to_have_count(0);editor.click(button='right');expect(context()).to_have_count(0);expect(floating()).to_have_count(0);page.get_by_label('Read only',exact=True).uncheck();page.get_by_label('Disabled',exact=True).check();editor.click(button='right',force=True);expect(context()).to_have_count(0);page.get_by_label('Disabled',exact=True).uncheck();checks.append('Readonly/disabled close open menus and do not intercept the native context action.')
 # Test a live menu at the small viewport's lower/right editor edge.
 page.set_viewport_size({'width':390,'height':844});editor.scroll_into_view_if_needed();editor.click(button='right',position={'x':320,'y':310});expect(context()).to_be_visible();box=context().bounding_box();assert box['x']>=0 and box['x']+box['width']<=390 and box['y']>=0 and box['y']+box['height']<=844,box
 page.screenshot(path=str(OUT/'inkwell-v3-context-mobile.png'));page.keyboard.press('Escape');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');checks.append('390px right-click menu clamps to viewport without page overflow.')
 page.set_viewport_size({'width':1440,'height':1100});replace('<p>A considered place for useful ideas.</p>');select();expect(floating()).to_be_visible();page.screenshot(path=str(OUT/'inkwell-v3-floating.png'));page.get_by_role('button',name='Selection link',exact=True).click();page.screenshot(path=str(OUT/'inkwell-v3-link.png'));page.keyboard.press('Escape')
 page.emulate_media(color_scheme='dark',reduced_motion='reduce');select();editor.press('Shift+F10');expect(context().get_by_role('menuitemcheckbox',name='Bold',exact=True)).to_be_focused();expect(context()).to_be_visible();page.screenshot(path=str(OUT/'inkwell-v3-context-dark.png'));page.keyboard.press('Escape');checks.append('Context surfaces render in dark/reduced-motion mode without runtime errors.')
 page.emulate_media(color_scheme='light');page.get_by_text('Try a sample document',exact=True).click();page.get_by_role('button',name='Sample document',exact=True).click();page.get_by_role('option',name='Meeting notes',exact=True).click();page.get_by_role('button',name='Load sample',exact=True).click();expect(editor.locator('h2')).to_have_text('Team working session');expect(editor.get_by_role('checkbox')).to_have_count(1);page.get_by_label('Document title',exact=True).fill('Workshop notes')
 with page.expect_download() as download:page.get_by_role('button',name='Export HTML',exact=False).click()
 assert download.value.suggested_filename=='Workshop notes.html';checks.append('Sample chooser loads a real structured document; entered title names the exported file.')
 page.get_by_role('button',name='Restore sample',exact=True).click();page.get_by_text('Try a sample document',exact=True).click();page.get_by_text('Test an external content update',exact=True).click();page.evaluate('scrollTo(0,0)');page.screenshot(path=str(OUT/'inkwell-v3-desktop.png'),full_page=True);page.set_viewport_size({'width':390,'height':844});page.screenshot(path=str(OUT/'inkwell-v3-mobile.png'),full_page=True);page.emulate_media(color_scheme='dark');page.screenshot(path=str(OUT/'inkwell-v3-dark-mobile.png'),full_page=True)
 assert not errors,errors;b.close()
(OUT/'contextual-checks.json').write_text(json.dumps(checks,indent=2));print(json.dumps(checks,indent=2))
